class ConnectionManager:
    def __init__(self):
        self.active_connections: Set[WebSocket] = set()

    async def connect(self, websocket: WebSocket, subprotocol: Optional[str] = None):
        await websocket.accept(subprotocol=subprotocol)
        self.active_connections.add(websocket)

    def disconnect(self, websocket: WebSocket):
        if websocket in self.active_connections:
            self.active_connections.remove(websocket)

    async def broadcast(self, message: dict):
        for connection in list(self.active_connections):
            try:
                await connection.send_json(message)
            except Exception as e:
                # A dead/closed client is expected and routine (browser tab closed, network
                # drop) -- disconnecting it is correct, not an error to surface loudly. Still
                # printed (not silently swallowed) so a genuinely unexpected send failure
                # doesn't vanish without a trace.
                print(f"⚠️ [WebSocket] Dropping dead connection during broadcast: {e}")
                self.disconnect(connection)


manager_ws = ConnectionManager()


async def poll_new_alerts():
    last_seen_id = None
    while True:
        try:
            with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
                if last_seen_id is None:
                    # PostgreSQL has no built-in MAX() aggregate for uuid (unlike int/text/timestamp);
                    # ORDER BY ... DESC LIMIT 1 gives the same "most recently created" row since
                    # UUIDv7 sorts chronologically just like the old integer id did.
                    cur.execute("SELECT id FROM public.runtime_alerts ORDER BY id DESC LIMIT 1")
                    res = cur.fetchone()
                    last_seen_id = res["id"] if res else None  # None while the table is empty

                cur.execute("""
                    SELECT r.id,
                           CASE UPPER(r.priority)
                               WHEN 'EMERGENCY' THEN 'CRITICAL' WHEN 'ALERT' THEN 'CRITICAL'
                               WHEN 'ERROR' THEN 'HIGH' WHEN 'WARNING' THEN 'MEDIUM'
                               WHEN 'NOTICE' THEN 'LOW' WHEN 'INFORMATIONAL' THEN 'INFO'
                               WHEN 'DEBUG' THEN 'INFO'
                               WHEN 'CRITICAL' THEN 'CRITICAL' WHEN 'HIGH' THEN 'HIGH'
                               WHEN 'MEDIUM' THEN 'MEDIUM' WHEN 'LOW' THEN 'LOW'
                               ELSE 'INFO'
                           END as priority,
                           r.rule_name, r.alert_text, r.detected_at, i.asset_name
                    FROM public.runtime_alerts r
                    LEFT JOIN public.infra_inventory i ON r.asset_id = i.id
                    WHERE r.id > %s AND r.rule_name NOT IN (
                        'Terminal shell in container', 'Unauthorized file access', 'ZEEK-CONN-HEARTBEAT',
                        'Drop and execute new binary in container', 'Read sensitive file untrusted',
                        'Falco internal: syscall event drop', 'PTRACE attached to process'
                    )
                    ORDER BY r.id ASC
                """, (last_seen_id,))
                new_alerts = cur.fetchall()
                for alert in new_alerts:
                    last_seen_id = max(last_seen_id, alert["id"])
                    if isinstance(alert["detected_at"], datetime):
                        alert["detected_at"] = alert["detected_at"].isoformat()
                    await manager_ws.broadcast({
                        "type": "new_alert",
                        "data": alert
                    })
        except Exception as e:
            print(f"⚠️ [WS-Poller] Error polling alerts: {e}")
        await asyncio.sleep(2)


def _tcp_ping_asset(endpoint):
    """Blocking TCP-connect probe. Returns (is_online, latency_ms). Runs in a worker thread."""
    if not endpoint:
        return False, None
    clean_host = endpoint.split("://")[-1].split("/")[0].split(":")[0]
    try:
        _t0 = time.time()
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.settimeout(1.0)
        s.connect((clean_host, 80 if "http" in endpoint else 22))
        s.close()
        return True, round((time.time() - _t0) * 1000, 1)
    except Exception:
        return False, None



async def poll_asset_status():
    """
    Background worker that continuously verifies asset connectivity (TCP probe & Wazuh status),
    updates last_seen timestamp in the DB whenever an asset is online/active, and broadcasts
    asset status updates to connected WebSocket clients in real-time.

    The per-asset TCP probe is blocking with a 1s timeout; with ~95 assets (many unreachable)
    running them one-by-one on the event loop froze *every* HTTP request for up to ~95s every
    cycle -- that's what left the ITDR / health / alerts views stuck on "Cargando...". The
    probes now run concurrently in a thread pool so the event loop stays responsive.
    """
    while True:
        try:
            with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute("SELECT id, asset_name, endpoint, status, agent_id, last_seen FROM public.infra_inventory")
                assets = cur.fetchall()

            ping_results = await asyncio.gather(
                *[asyncio.to_thread(_tcp_ping_asset, a["endpoint"]) for a in assets]
            )

            online_ids = []
            for asset, (is_online, latency_ms) in zip(assets, ping_results):
                current_status = asset["status"]
                agent_id = asset["agent_id"]
                prev_last_seen = asset["last_seen"]
                seen_now = is_online or current_status == "active" or bool(agent_id)
                if seen_now:
                    online_ids.append(asset["id"])

                await manager_ws.broadcast({
                    "type": "asset_status_update",
                    "data": {
                        "asset_name": asset["asset_name"],
                        "endpoint": asset["endpoint"],
                        "status": current_status,
                        "ping_ok": is_online,
                        "latency_ms": latency_ms,
                        "last_seen": datetime.now().isoformat() if seen_now else (prev_last_seen.isoformat() if prev_last_seen and isinstance(prev_last_seen, datetime) else None)
                    }
                })

            # One batched UPDATE instead of one round-trip per online asset.
            if online_ids:
                with db_manager.get_db_cursor() as cur_up:
                    cur_up.execute(
                        # psycopg2 adapts a Python list of str to a text[] literal; without an
                        # explicit cast Postgres refuses "uuid = text" (no such operator).
                        "UPDATE public.infra_inventory SET last_seen = NOW() WHERE id = ANY(%s::uuid[])",
                        (online_ids,)
                    )
        except Exception as e:
            print(f"⚠️ [Asset-Verifier] Error verifying asset statuses: {e}")
        await asyncio.sleep(10)





def json_serializable(data):
    if isinstance(data, dict):
        return {k: json_serializable(v) for k, v in data.items()}
    elif isinstance(data, list):
        return [json_serializable(v) for v in data]
    elif hasattr(data, "strftime"):
        return data.strftime("%Y-%m-%d %H:%M")
    return data



def _run_authentik_ssh_command(remote_shell_snippet: str, timeout: int = 40) -> subprocess.CompletedProcess:
    """
    Runs a python3-in-Django-shell one-liner on the Authentik host over SSH.

    `remote_shell_snippet` MUST be a single physical line -- only `;` and expressions, no
    literal newlines and no statement-level `for`/`if` blocks. `manage.py shell -c` runs the
    string through `exec()`; a multi-line snippet built with `\\n` in a Python string literal
    passes a *literal* backslash-n to the remote `exec()`, which is a SyntaxError there (this
    silently broke both /api/users and /api/users/role -- they returned []/404 forever).

    Uses an argument list, not a local shell string -- the previous version built `cmd` as an
    f-string interpolating request-body fields directly (username/role in
    update_authentik_user_role) and ran it through a local command interpreter, a real,
    exploitable command injection. ssh itself still receives the remote command as a single
    argument here; callers must still validate/escape any interpolated value against the remote
    Python string themselves (see ROLE_ALLOWLIST and _validate_authentik_username below).

    Default timeout is 40s: a cold `manage.py shell` on this Authentik build spends ~15-20s just
    importing apps before it runs the snippet.
    """
    return subprocess.run(
        ["ssh", "-o", "StrictHostKeyChecking=no", "-o", "ConnectTimeout=10",
         "-i", org_config.AUTHENTIK_SSH_KEY, org_config.AUTHENTIK_SSH_TARGET,
         f'docker exec {org_config.AUTHENTIK_SERVER_CONTAINER} python3 manage.py shell -c "{remote_shell_snippet}"'],
        capture_output=True, text=True, timeout=timeout
    )
